// Everything that ties K 線衝浪 to the SNEK Arcade lives in this one file.
// To run the game on its own (e.g. as a standalone project), replace this file only — see README.md.
import { AnalyticsService } from '../../platform/AnalyticsService.ts';

/** back to the arcade lobby (the game is served from /game/surfer/, the lobby from /game/) */
export const ARCADE_URL = '../#/';
/** public URL used in share links */
export const GAME_URL = 'https://www.snek.com.tw/game/surfer/';

// The language is chosen in the arcade lobby only (no in-game language button).
// Same keys and priority as the lobby's I18nService: saved choice first, then ?lang=.
const ARCADE_LOCALE_KEYS = ['snek_locale', 'snek_arcade:locale', 'snek_lang'];
export function readArcadeLocale(): string | null {
  try {
    for (const k of ARCADE_LOCALE_KEYS) {
      const v = localStorage.getItem(k);
      if (v) return v;
    }
  } catch {
    /* storage blocked */
  }
  return null;
}

export const track = {
  pageView: () => AnalyticsService.trackPageView('/surfer', 'SNEK K 線衝浪'),
  start: (mode: string) => AnalyticsService.trackGameStart('surfer', { mode }),
  over: (p: {
    /** realized profit */
    score: number;
    /** candles passed */
    candles: number;
    seconds: number;
    /** liquidated | quit */
    reason: string;
    /** highest leverage reached */
    leverage: number;
    mode: string;
  }) =>
    AnalyticsService.trackGameOver({
      game_id: 'surfer',
      score: p.score,
      level: p.candles,
      duration_sec: p.seconds,
      reason: p.reason,
      leverage: p.leverage,
      mode: p.mode,
    }),
};
