// Best scores and settings in localStorage.

export interface Save {
  v: 1;
  /** best realized profit in one run */
  best: number;
  /** most candles passed in one run */
  bestCandles: number;
  /** best realized profit on a daily chart, and which day */
  daily: { date: string; best: number };
  runs: number;
  muted: boolean;
  /** the how-to-play panel has been shown once */
  seenHowto: boolean;
}

const KEY = 'snek-surfer:save';

export const freshSave = (): Save => ({
  v: 1,
  best: 0,
  bestCandles: 0,
  daily: { date: '', best: 0 },
  runs: 0,
  muted: false,
  seenHowto: false,
});

const num = (n: unknown, max: number) =>
  typeof n === 'number' && Number.isFinite(n) ? Math.min(max, Math.max(0, Math.floor(n))) : 0;

/** accept only what a save should contain; anything else becomes the default */
export function sanitize(raw: unknown): Save {
  const s = freshSave();
  if (!raw || typeof raw !== 'object') return s;
  const r = raw as Record<string, unknown>;
  s.best = num(r.best, 1e12);
  s.bestCandles = num(r.bestCandles, 1e9);
  s.runs = num(r.runs, 1e9);
  s.muted = r.muted === true;
  s.seenHowto = r.seenHowto === true;
  const d = r.daily as Save['daily'] | undefined;
  if (d && typeof d === 'object' && typeof d.date === 'string')
    s.daily = { date: d.date.slice(0, 10), best: num(d.best, 1e12) };
  return s;
}

export function loadSave(): Save {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) return sanitize(JSON.parse(raw));
  } catch {
    /* blocked storage or bad JSON */
  }
  return freshSave();
}

export function storeSave(s: Save): void {
  try {
    localStorage.setItem(KEY, JSON.stringify(s));
  } catch {
    /* private mode etc. */
  }
}

/** record a finished run; returns what became a new record */
export function recordRun(
  s: Save,
  r: { realized: number; candles: number; dailyDate: string | null },
): { best: boolean; daily: boolean } {
  const out = { best: false, daily: false };
  s.runs++;
  if (r.realized > s.best) {
    s.best = r.realized;
    out.best = true;
  }
  s.bestCandles = Math.max(s.bestCandles, r.candles);
  if (r.dailyDate) {
    if (s.daily.date !== r.dailyDate) s.daily = { date: r.dailyDate, best: 0 };
    if (r.realized > s.daily.best) {
      s.daily.best = r.realized;
      out.daily = true;
    }
  }
  return out;
}
