// DESIGN.md explains the rules in 正體中文. Keep the two in step.

// ---------------------------------------------------------------- movement
/** candles per second at the start and at the limit */
export const SPEED_START = 6;
export const SPEED_MAX = 12;
/** distance (candles) over which the speed closes ~63% of the gap to SPEED_MAX */
export const SPEED_RAMP = 350;
export const speedAt = (x: number): number =>
  SPEED_START + (SPEED_MAX - SPEED_START) * (1 - Math.exp(-Math.max(0, x) / SPEED_RAMP));

export const GRAVITY = 58;
export const JUMP_V = 15;
