export const JUMP2_V = 13;
export const AIR_JUMPS = 1;
/** letting go early multiplies the upward speed by this (short hop) */
export const JUMP_CUT = 0.4;
/** a jump cannot be cut before this age, so a quick tap still hops */
export const JUMP_MIN_TIME = 0.06;
/** a jump still counts this long after running off an edge */
export const COYOTE = 0.09;
/** a press is remembered this long before landing */
export const JUMP_BUFFER = 0.12;
/** the board glides up or down steps this small without a jump */
export const STEP = 0.35;
/** how long a full jump stays in the air on flat ground */
export const AIR_TIME = (2 * JUMP_V) / GRAVITY;
/** highest point of a full single jump */
export const JUMP_APEX = (JUMP_V * JUMP_V) / (2 * GRAVITY);

