// ---------------------------------------------------------------- leverage and margin
/**
 * Leverage has no cap. Holding at a take-profit gate moves one tier up, taking profit resets to 1x.
 * The first tiers are this table; after it every tier adds LEVERAGE_STEP.
 */
export const LEVERAGE = [1, 2, 3, 4, 5, 7, 10, 15, 20, 30, 50, 75, 100] as const;
export const LEVERAGE_STEP = 50;
export const leverageAt = (tier: number): number =>
  tier < LEVERAGE.length
    ? LEVERAGE[Math.max(0, tier)]
    : LEVERAGE[LEVERAGE.length - 1] + LEVERAGE_STEP * (tier - LEVERAGE.length + 1);
/**
 * The higher the leverage has been, the faster the whole game runs, without limit, and taking
 * profit does not slow it down again: with n the highest tier reached in the run, the clock runs
 * 1 + TEMPO_STEP * n times as fast. Everything speeds up together (the chart, the jump, the fall),
 * so a jump still carries exactly as far along the chart and every chart stays passable; what
 * shrinks is the time to react.
 */
export const TEMPO_STEP = 0.05;
export const tempo = (tier: number): number => 1 + TEMPO_STEP * Math.max(0, tier);
/** margin ratio added by one hit at each tier; at 100% the position is liquidated. From 20x up, one hit does it. */
export const HIT_MARGIN = [34, 40, 45, 50, 60, 67, 75, 85, 100] as const;
export const hitMargin = (tier: number): number =>
  HIT_MARGIN[Math.min(HIT_MARGIN.length - 1, Math.max(0, tier))];
