// ---------------------------------------------------------------- shorts in the air
/**
 * The shorts' air force: a fighter jet comes in from the right. Its path is tied to the player: it
 * is over the middle of its candle exactly when the player is, and FLYER_PACE times as far beyond
 * it as the player is short of it. So against the chart it flies left at FLYER_PACE times the
 * player's speed, and it meets the player over flat ground whatever the leverage does to the clock.
 */
export const FLYER_PACE = 0.5;
/** where a jet is when the player is at px: `i` is the candle it meets the player over */
export const flyerX = (i: number, px: number): number => i + 0.5 + FLYER_PACE * (i + 0.5 - px);
/** half its length, and its height */
export const FLYER_HALF_W = 0.45;
export const FLYER_H = 0.6;
/** its underside above the ground: a low one has to be jumped, a high one passes over a rider on the ground */
export const FLYER_LOW = 0.1;
export const FLYER_HIGH = 1.3;
/** the bounce off a squeezed jet, and what it pays before leverage */
export const FLYER_BOUNCE = 14;
export const AIR_SQUEEZE_PROFIT = 30;
/** squeezes in a row without touching the ground pay 2x, 3x ... up to this */
export const CHAIN_MAX = 5;
/** the first block that has jets, the first with formations of two, and the first where they are armed */
export const FLYER_FROM = 1;
export const SQUAD_FROM = 3;
export const ARMED_FROM = 4;
/**
 * Formations. pair: two low ones, one bounce apart. stair: a low one, then a high one where the
 * bounce off the first comes down. dive: a high one, then a low one right behind it, with just
 * the time to take off in between.
 * Armed, from ARMED_FROM on. gunner: a high jet that fires a bullet down at the player; the bullet
 * arrives first, low, and the jet passes overhead after it. bomber: a high jet that passes overhead
 * and bombs a candle behind it out of the chart, leaving a gap.
 * The times are the seconds between the two meetings.
 */
export type Squad = 'single' | 'pair' | 'stair' | 'dive' | 'gunner' | 'bomber';
export const PAIR_AIR = 0.47;
export const STAIR_AIR = 0.36;
export const DIVE_AIR = 0.27;
/** a held jump taken just before the bullet comes down on the jet this much later */
export const GUN_AIR = 0.3;
/** how often each formation comes up, out of 100: before the jets are armed, and after */
export const SQUAD_MIX: [Squad, number][] = [
  ['single', 30],
  ['pair', 25],
  ['stair', 25],
  ['dive', 20],
];
export const ARMED_MIX: [Squad, number][] = [
  ['single', 16],
  ['pair', 14],
  ['stair', 14],
  ['dive', 14],
  ['gunner', 22],
  ['bomber', 20],
];
/**
 * A bullet is tied to the player the same way a jet is, only much faster. It meets the player
 * `gap` candles before its jet does, so it leaves the jet's nose when the two are in the same place.
 */
export const BULLET_PACE = 2.5;
export const bulletX = (i: number, px: number): number => i + 0.5 + BULLET_PACE * (i + 0.5 - px);
/** half its length and half its height, and the height of its middle above the ground where it meets the player */
export const BULLET_HALF_W = 0.2;
export const BULLET_HALF_H = 0.12;
export const BULLET_Y = 0.35;
/** how far ahead of the player the jet is when it fires a bullet that arrives `gap` candles before it */
export const fireAhead = (gap: number): number =>
  ((1 + FLYER_PACE) * (1 + BULLET_PACE) * gap) / (BULLET_PACE - FLYER_PACE);
/** how many candles before the bullet reaches the player that is */
export const fireLead = (gap: number): number => fireAhead(gap) / (1 + BULLET_PACE);
/**
 * the height of a bullet's middle above the ground when it is `ahead` candles in front of the
 * player: it comes down in a straight line from the nose of its jet
 */
export const bulletAlt = (gap: number, ahead: number): number =>
  BULLET_Y + ((FLYER_HIGH + FLYER_H / 2 - BULLET_Y) / fireAhead(gap)) * ahead;
/** a bombed candle is gone once the player is this many candles from it, and the bomb falls for this many before that */
export const BOMB_NOTICE = 5;
export const BOMB_FALL = 2;
/** the player is told this many candles before the meeting, and the edge of the screen shows where */
export const FLYER_WARN = 10;

