// ---------------------------------------------------------------- market events
/**
 * Now and then the market does something for a whole block (the stretch between two take-profit
 * gates). Some are good news, some are bad.
 *
 * - airdrop: money bags come down on parachutes
 * - boost: big money comes in, every coin is big and pays 50
 * - megaboost: a whale doubles down, every coin is huge and pays 100
 * - exit: big money sells out, the chart runs faster and coins pay next to nothing
 * - wicks: a storm of wicks striking out of the sky, and a close call over one pays five times as much
 * - bearmarket: the big bear attacks. The ground cracks, and its paws hang low over some of the
 *   cracks (hop under, do not jump high); at the end the bear itself lies in the way: land on its head
 */
export type MarketEvent = 'airdrop' | 'boost' | 'megaboost' | 'exit' | 'wicks' | 'bearmarket';
/** the first block that may have an event (0 = the first block), and the chance in a block that may */
export const EVENT_FROM = 2;
export const EVENT_CHANCE = 0.45;
/** how often each event comes up, out of 100 */
export const EVENT_MIX: [MarketEvent, number][] = [
  ['airdrop', 16],
  ['boost', 14],
  ['megaboost', 6],
  ['exit', 12],
  ['wicks', 22],
  ['bearmarket', 30],
];
/**
 * A paw hangs over a crack in the ground, this far above its edges: feet higher than this under it
 * get swatted. A short hop (a tap) stays below it, a held jump (apex JUMP_APEX) does not.
 */
export const PAW_FLOOR = 1.7;
/** seconds in the air for the shortest hop: the button let go at once */
export const HOP_AIR = (() => {
  const v = (JUMP_V - GRAVITY * JUMP_MIN_TIME) * JUMP_CUT;
  const h = JUMP_V * JUMP_MIN_TIME - (GRAVITY / 2) * JUMP_MIN_TIME ** 2;
  return JUMP_MIN_TIME + (v + Math.sqrt(v * v + 2 * GRAVITY * h)) / GRAVITY;
})();
/** the big bear: how many candles before the gate's flat ground it lies, and its size */
export const BOSS_BACK = 9;
export const BOSS_W = 2;
export const BOSS_H = 1.6;
/** falling onto its head counts while the feet are no lower than this below the top */
export const BOSS_STOMP_DEPTH = 0.6;
/** the bounce off its head, what squeezing it pays before leverage, and what it adds to the gauge */
export const BOSS_V = 18;
export const BIG_SQUEEZE_PROFIT = 200;
export const BIG_SQUEEZE_FOMO = 30;
/** unrealized profit of an ordinary coin during each event, before leverage */
export const BOOST_COIN = 50;
export const MEGABOOST_COIN = 100;
export const EXIT_COIN = 1;
export const coinProfit = (market: MarketEvent | null): number =>
  market === 'boost'
    ? BOOST_COIN
    : market === 'megaboost'
      ? MEGABOOST_COIN
      : market === 'exit'
        ? EXIT_COIN
        : COIN_PROFIT;
/** an airdropped money bag pays this, before leverage, and fills this much of the FOMO gauge */
export const BAG_PROFIT = 40;
export const BAG_FOMO = 6;
/** how high the bags hang over the ground: one to ride into, two for a jump, one for a full jump */
export const BAG_HEIGHTS = [0.55, 1.6, 1.6, 2.7];
/** the chart runs this much faster while big money sells out */
export const EXIT_SPEED = 1.2;
export const marketSpeed = (market: MarketEvent | null): number =>
  market === 'exit' ? EXIT_SPEED : 1;
/** a close call pays this many times more during a wick storm */
export const WICKS_GRAZE = 5;
/**
 * In a wick storm the wicks come out of the sky: each one strikes its candle when the player is
 * this many candles from it. Until then only its outline shows. (The rules treat it as a wick all
 * along; nobody can be there before it strikes.)
 */
export const WICK_STRIKE = 5;
/**
 * A wick storm is dense. Between two hazards there are only this many seconds of quiet chart,
 * however early in the run it comes (the same as CALM_MIN, the shortest calm of a late block);
 * this is the chance that a wick is a row of two or three; and tall wicks, which stand alone and
 * need a longer run-up, are rarer than elsewhere.
 */
export const STORM_CALM = 0.34;
export const STORM_ROW = 0.9;
export const STORM_TALL = 0.12;

// ---------------------------------------------------------------- pace
/**
 * Seconds of quiet chart between two hazards. It shrinks block by block, so the run keeps getting
 * harder after the speed has topped out.
 */
export const CALM_START = 0.66;
export const CALM_STEP = 0.03;
export const CALM_MIN = 0.34;
export const calmTime = (block: number): number =>
  Math.max(CALM_MIN, CALM_START - CALM_STEP * block);

// ---------------------------------------------------------------- market phases
export type Phase = 'sideways' | 'bull' | 'bear' | 'pump' | 'crash';
export const PHASES: readonly Phase[] = ['sideways', 'bull', 'bear', 'pump', 'crash'];

/** fixed simulation step */
export const DT = 1 / 120;
