// Canvas 2D renderer: the chart, hazards, pickups, the surfing SNEK and the visual effects.
// It only reads the simulation. Layout is computed from the canvas size, so it fits phones and desktops.
import { type Candle, itemPos } from './chart.ts';
import {
  BEAR_H,
  BEAR_HALF_W,
  BOMB_FALL,
  BOMB_NOTICE,
  BOSS_H,
  BOSS_W,
  BULLET_HALF_W,
  BULLET_Y,
  bulletAlt,
  bulletX,
  FLYER_H,
  FLYER_HALF_W,
  FLYER_WARN,
  FUD_R,
  fireLead,
  flyerX,
  GATE_HEIGHT,
  type ItemKind,
  PAW_FLOOR,
  ROCKET_FUEL,
  SPIKE_W,
  SPOUT_HALF,
  TIER_HEAD,
  WHALE_BACK,
  WHALE_BLOWHOLE,
  WICK_STRIKE,
} from './data.ts';
import { HEAD_STYLES, headSvg } from './heads.ts';
import { MOON_FILL, Moon } from './moon.ts';
import type { Run } from './sim.ts';

const GREEN = '#2ee58a';
const RED = '#ff4d5e';
const GOLD = '#ffc21f';
const INK = '#05080a';
/** trail and badge colour per leverage tier */
const TIER_COLORS = [
  '#6fe0a6',
  '#ff9f48',
  '#ff84bf',
  '#ff84bf',
  '#ff5964',
  '#ff5964',
  '#7db8ff',
  '#7db8ff',
  '#ffc21f',
];
/** the colour of a leverage tier; from 20x up it stays gold */
export const tierColor = (tier: number): string =>
  TIER_COLORS[Math.min(TIER_COLORS.length - 1, Math.max(0, tier))];

const FONT = '"Arial Black", "Noto Sans TC", "PingFang TC", "Microsoft JhengHei", sans-serif';

/** how high the bull's back is above the ground, in candles: this is where its rider sits */
const BULL_BACK = 1.45;

/** where the neck meets the board, as a fraction of the head image (before it is flipped to face right) */
const NECK = { x: 0.46, y: 0.975 };

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  max: number;
  color: string;
  size: number;
  gravity: number;
}
interface FloatText {
  x: number;
  y: number;
  str: string;
  color: string;
  life: number;
  max: number;
  size: number;
}

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

export class Renderer {
  private readonly ctx: CanvasRenderingContext2D;
  /** CSS pixels */
  w = 0;
  h = 0;
  private dpr = 1;
  /** pixels per candle */
  u = 40;
  /** screen x of the player */
  px = 0;
  private baseY = 0;
  private camY = 0;
  private shake = 0;
  private flash = 0;
  private flashColor = RED;
  private parts: Particle[] = [];
  private texts: FloatText[] = [];
  private trail: { x: number; y: number }[] = [];
  private readonly heads: HTMLImageElement[] = [];
  private readonly stars: { x: number; y: number; r: number; p: number }[] = [];
  private readonly moon = new Moon();
  /** how hard it is raining money, 0..1 (eases in and out with the airdrop) */
  private rain = 0;
  /** how much of a wick storm is on, 0..1, and when each of its wicks struck (-9 = before it was seen) */
  private storm = 0;
  private readonly struck = new Map<number, number>();
  /** the bull: 0 = not there, 1 = carrying the rider; it eases in from behind and out ahead */
  private bullIn = 0;
  /** the level of the ground the bull runs on, smoothed */
  private bullY = 0;
  /** paws of the big bear that have already come down behind the player */
  private readonly slammed = new Set<number>();
  /** bombed gaps that have gone off, and bullets that have hit the ground */
  private readonly bombed = new Set<number>();
  private readonly spent = new Set<number>();
  private bg: CanvasGradient | null = null;
  /** words drawn on the chart, set by main.ts in the player's language */
  labels = { gate: 'TP', hold: 'HODL' };

  constructor(private readonly canvas: HTMLCanvasElement) {
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('no 2d canvas');
    this.ctx = ctx;
    for (const id of TIER_HEAD) {
      const style = HEAD_STYLES.find((s) => s.id === id);
      const img = new Image();
      if (style) img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(headSvg(style))}`;
      this.heads.push(img);
    }
    // a fixed star field (same on every device)
    let s = 12345;
    const rnd = () => {
      s = (s * 1103515245 + 12345) & 0x7fffffff;
      return s / 0x7fffffff;
    };
    for (let i = 0; i < 70; i++)
      this.stars.push({ x: rnd(), y: rnd() * 0.7, r: 0.6 + rnd() * 1.2, p: 0.5 + rnd() * 2 });
    this.resize();
  }

  resize(): void {
    const w = this.canvas.clientWidth || window.innerWidth;
    const h = this.canvas.clientHeight || window.innerHeight;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.w = w;
    this.h = h;
    this.canvas.width = Math.round(w * this.dpr);
    this.canvas.height = Math.round(h * this.dpr);
    // phones (portrait) see about 11 candles across, wide screens at most 18
    this.u = Math.max(w / 18, Math.min(h / 12, w / 11));
    this.px = w * (w < h ? 0.22 : 0.24);
    this.baseY = h * 0.62;
    const g = this.ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#070b12');
    g.addColorStop(0.6, '#0d1522');
    g.addColorStop(1, '#101c2b');
    this.bg = g;
  }

  /** start of a run: snap the camera and clear the effects */
  reset(run: Run): void {
    this.camY = run.y;
    this.parts = [];
    this.texts = [];
    this.trail = [];
    this.shake = 0;
    this.flash = 0;
    this.bullIn = 0;
    this.bullY = run.y;
    this.slammed.clear();
    this.bombed.clear();
    this.struck.clear();
    this.spent.clear();
  }

  // ------------------------------------------------------------------ effects
  burst(x: number, y: number, color: string, n: number, speed = 5, gravity = 14): void {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const v = speed * (0.35 + Math.random() * 0.65);
      const life = 0.35 + Math.random() * 0.45;
      this.parts.push({
        x,
        y,
        vx: Math.cos(a) * v,
        vy: Math.sin(a) * v + speed * 0.3,
        life,
        max: life,
        color,
        size: 0.06 + Math.random() * 0.08,
        gravity,
      });
    }
    if (this.parts.length > 400) this.parts.splice(0, this.parts.length - 400);
  }

  /** a word that floats up from the player */
  say(run: Run, str: string, color: string, size = 1): void {
    const busy = this.texts.filter((t) => t.life > t.max - 0.5).length;
    this.texts.push({
      x: run.x + 0.2,
      y: run.y + 1.5 + busy * 0.55,
      str,
      color,
      life: 1.3,
      max: 1.3,
      size,
    });
  }

  shakeBy(seconds: number): void {
    this.shake = Math.max(this.shake, seconds);
  }
  flashBy(color: string, amount = 1): void {
    this.flash = amount;
    this.flashColor = color;
  }

  // ------------------------------------------------------------------ frame
  draw(run: Run, t: number, dt: number, live: boolean): void {
    const { ctx, w, h, u } = this;
    const chart = run.chart;
    const pi = Math.floor(run.x);

    // camera: follow the ground under and ahead of the player, and never lose the player
    const under = chart.solidFrom(pi).top;
    let ahead = 0;
    let n = 0;
    for (let j = pi + 1; j <= pi + 5; j++) {
      const c = chart.at(j);
      if (!c.gap) {
        ahead += c.top;
        n++;
      }
    }
    let target = n ? under * 0.5 + (ahead / n) * 0.5 : under;
    target = Math.max(target, run.y - 2.4);
    this.camY += (target - this.camY) * (1 - Math.exp(-dt * 4.5));
    const topLimit = Math.max(h * 0.2, 120);
    this.camY = Math.max(this.camY, run.y + 1.1 - (this.baseY - topLimit) / u);
    this.camY = Math.min(this.camY, run.y + (h * 0.86 - this.baseY) / u);
    const camY = this.camY;
    const sx = (wx: number) => this.px + (wx - run.x) * u;
    const sy = (wy: number) => this.baseY - (wy - camY) * u;

    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.globalAlpha = 1;
    ctx.fillStyle = this.bg ?? '#0b1018';
    ctx.fillRect(0, 0, w, h);

    this.drawSky(t);
    // an airdrop: it rains money behind the chart
    this.rain +=
      ((run.market === 'airdrop' && !run.over ? 1 : 0) - this.rain) * Math.min(1, dt * 3);
    if (this.rain > 0.02) this.drawShower(t, this.rain);
    // a wick storm: the sky goes dark and lightning plays in the clouds
    this.storm +=
      ((run.market === 'wicks' && !run.over ? 1 : 0) - this.storm) * Math.min(1, dt * 3);
    if (this.storm > 0.02) this.drawStorm(t, this.storm);

    ctx.save();
    if (this.shake > 0) {
      this.shake = Math.max(0, this.shake - dt);
      const k = Math.min(1, this.shake / 0.25) * 7;
      ctx.translate((Math.random() - 0.5) * k, (Math.random() - 0.5) * k);
    }

    this.drawGrid(run.x, camY, sx, sy);

    const iMin = Math.floor(run.x - this.px / u) - 1;
    const iMax = Math.ceil(run.x + (w - this.px) / u) + 1;
    const cs: Candle[] = [];
    for (let i = iMin; i <= iMax; i++) {
      if (i >= 0) cs.push(chart.at(i));
      else {
        // before the first candle: plain history, so the left edge of the screen is never empty
        const first = chart.at(0);
        const wave = Math.sin(i * 1.7) * 0.12;
        cs.push({
          ...first,
          i,
          top: first.top + wave,
          bottom: first.top + wave - 0.3 - Math.abs(Math.sin(i * 2.3)) * 0.4,
          low: first.top + wave - 1,
          high: first.top + wave + 0.08,
          green: Math.sin(i * 2.9) > -0.3,
          coins: [],
          item: null,
          gate: false,
          spike: 0,
          fud: 0,
          bear: false,
          event: null,
          bounce: false,
          spout: false,
        });
      }
    }

    // volume bars along the bottom, like a real chart
    const vh = h * 0.1;
    for (const c of cs) {
      if (c.gap || c.bounce) continue;
      ctx.fillStyle = c.green ? 'rgba(46,229,138,0.2)' : 'rgba(255,77,94,0.2)';
      ctx.fillRect(sx(c.i + 0.15), h - c.vol * vh, u * 0.7, c.vol * vh);
    }

    for (const c of cs) {
      // a whale's stretch is water, not candles
      if (c.event === 'whale' && (c.gap || c.bounce)) continue;
      // a candle that is about to be bombed still stands until the bomb lands
      if (c.crater && c.i >= 0) {
        const first = chart.at(c.i - 1).crater ? c.i - 1 : c.i;
        if (run.x < first - BOMB_NOTICE) {
          this.drawCandle(
            { ...c, gap: false, bottom: c.top - 0.28, low: c.top - 0.6, high: c.top + 0.06 },
            sx,
            sy,
          );
          continue;
        }
      }
      this.drawCandle(c, sx, sy);
    }
    // the whale lies in the liquidity it ate; look a little past both edges so it never pops in or out
    for (let i = Math.max(0, iMin - WHALE_BACK); i <= iMax + WHALE_BACK; i++) {
      const c = chart.at(i);
      if (c.spout) this.drawWhale(c, t, sx, sy);
    }
    for (const c of cs) {
      if (c.gate) this.drawGate(c, run, t, sx, sy);
      // a squeezed bear or a hazard smashed in a bull run is gone
      if (c.gap || c.i < 0 || run.isTaken(c.i, 6)) continue;
      if (c.spike > 0) {
        if (c.market === 'wicks') this.drawStrike(c, run, t, sx, sy);
        else this.drawSpike(c, t, sx, sy);
      }
      if (c.fud > 0) this.drawFud(c, t, sx, sy);
      if (c.bear) this.drawBear(c, t, sx, sy);
      if (c.boss) this.drawBoss(c, t, sx, sy);
    }
    // the paws of the big bear (a paw may start a candle or two off the left edge)
    for (let i = Math.max(0, iMin - 2); i <= iMax; i++) {
      const c = chart.at(i);
      if (!c.paw || (i > 0 && chart.at(i - 1).paw) || run.isTaken(i, 6)) continue;
      this.drawPaw(c, chart.at(i + 1).paw ? 2 : 1, run, t, sx, sy);
    }
    // the shorts' air force: where each jet and bullet is depends on where the player is, so look
    // past both edges
    for (let i = Math.max(0, pi - 6); i <= pi + FLYER_WARN + 8; i++) {
      const c = chart.at(i);
      if (c.crater && !chart.at(i - 1).crater) this.drawBombing(c, run, t, sx, sy);
      if (i > pi + FLYER_WARN || run.isTaken(i, 6)) continue;
      if (c.bullet > 0) this.drawBullet(c, run, t, sx, sy);
      if (c.flyer > 0) this.drawFlyer(c, run, t, sx, sy);
    }
    for (const c of cs) {
      for (let s = 0; s < c.coins.length; s++) {
        if (run.isTaken(c.i, s)) continue;
        const coin = c.coins[s];
        if (coin.bag) {
          this.drawBag(sx(coin.x), sy(coin.y), coin.x - run.x, coin.y - c.top, t + coin.x);
          continue;
        }
        const y = sy(coin.y);
        // big money in: big coins; big money out: small dull ones
        const size = coin.moon
          ? 1
          : c.market === 'megaboost'
            ? 1.85
            : c.market === 'boost'
              ? 1.45
              : c.market === 'exit'
                ? 0.65
                : 1;
        this.drawCoin(sx(coin.x), y, t + coin.x, coin.moon === true, size, c.market === 'exit');
      }
      if (c.item && !run.isTaken(c.i, 7)) {
        const p = itemPos(c);
        this.drawItem(c.item, sx(p.x), sy(p.y) + Math.sin(t * 3 + c.i) * u * 0.06, t);
      }
    }

    // the bull: it charges in from behind, carries the rider on its back, and runs off ahead
    const charging = run.bull > 0 && !run.over;
    this.bullIn += ((charging ? 1 : 0) - this.bullIn) * Math.min(1, dt * (charging ? 9 : 4));
    this.bullY += (chart.at(pi).top - this.bullY) * Math.min(1, dt * 16);
    /** how far the rider sits above the ground, in candles (a rocket flies clear of the bull) */
    const lift = run.flying ? 0 : BULL_BACK * this.bullIn;
    const riderY = charging && !run.flying ? Math.max(run.y, this.bullY) : run.y;

    // the trail is the player's own price line
    if (live) {
      const last = this.trail[this.trail.length - 1];
      if (!last || run.x - last.x > 0.12)
        this.trail.push({ x: run.x - 0.45, y: riderY + lift + 0.1 });
      if (this.trail.length > 70) this.trail.shift();
    }
    this.drawTrail(run, sx, sy);

    // spray off the back of the board
    if (live && run.grounded && this.parts.length < 300) {
      const life = 0.25 + Math.random() * 0.2;
      this.parts.push({
        x: run.x - (charging ? 1.1 : 0.55),
        y: (charging ? this.bullY : run.y) + 0.05,
        vx: run.speed * (0.25 + Math.random() * 0.3),
        vy: 1 + Math.random() * 2.5,
        life,
        max: life,
        color: run.bull > 0 ? GOLD : '#bfe6ff',
        size: (run.bull > 0 ? 0.07 : 0.04) + Math.random() * 0.05,
        gravity: 12,
      });
    }

    this.drawParticles(dt, sx, sy);
    if (this.bullIn > 0.02) {
      // coming, it slides in from the left; going, it pulls away to the right
      const away = (1 - this.bullIn) * u * (charging ? -7 : 9);
      const blink = charging && run.bull < 4 && Math.floor(t * 8) % 2 === 0;
      // while it carries the rider it leaps when the rider jumps: the two never come apart
      this.drawBull(
        this.px + away,
        sy(charging && !run.flying ? riderY : this.bullY),
        t,
        blink ? 0.55 : Math.min(1, this.bullIn * 1.6),
      );
    }
    if (!(run.over && run.end === 'liquidated'))
      this.drawPlayer(run, t, live, sy(riderY) - lift * u);
    this.drawTexts(dt, sx, sy);
    ctx.restore();

    // big money selling out, or a bear market: the edges of the screen go red
    if ((run.market === 'exit' || run.market === 'bearmarket') && !run.over) {
      const g = ctx.createRadialGradient(
        w / 2,
        h / 2,
        Math.min(w, h) * 0.4,
        w / 2,
        h / 2,
        Math.max(w, h) * 0.75,
      );
      g.addColorStop(0, 'rgba(255,77,94,0)');
      g.addColorStop(1, `rgba(255,77,94,${0.2 + 0.06 * Math.sin(t * 6)})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    }

    // bull run: the edges of the screen glow gold, and blink when it is about to end
    if (run.bull > 0 && !run.over) {
      const ending = run.bull < 4 && Math.floor(t * 8) % 2 === 0;
      const g = ctx.createRadialGradient(
        w / 2,
        h / 2,
        Math.min(w, h) * 0.35,
        w / 2,
        h / 2,
        Math.max(w, h) * 0.75,
      );
      g.addColorStop(0, 'rgba(255,194,31,0)');
      g.addColorStop(1, `rgba(255,194,31,${ending ? 0.12 : 0.3 + 0.08 * Math.sin(t * 10)})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    }

    if (this.flash > 0) {
      ctx.globalAlpha = this.flash * 0.28;
      ctx.fillStyle = this.flashColor;
      ctx.fillRect(0, 0, w, h);
      ctx.globalAlpha = 1;
      this.flash = Math.max(0, this.flash - dt * 3);
    }
  }

  private drawSky(t: number): void {
    const { ctx, w, h } = this;
    ctx.fillStyle = '#ffffff';
    for (const s of this.stars) {
      ctx.globalAlpha = 0.25 + 0.45 * Math.abs(Math.sin(t * s.p + s.x * 20));
      ctx.fillRect(s.x * w, s.y * h, s.r, s.r);
    }
    ctx.globalAlpha = 1;

    // the moon sits under the HUD on any screen shape, clear of the price scale on the right
    const r = clamp(Math.min(w, h) * 0.09, 30, 92);
    const mx = w - r - 70;
    // (on a narrow screen the news ticker runs across the top, so the moon hangs below it)
    const my = Math.max(h * 0.2, (w < 520 ? 182 : 118) + r);
    // its halo: light added to the sky
    const halo = ctx.createRadialGradient(mx, my, r * 0.48, mx, my, r * 1.6);
    halo.addColorStop(0, 'rgba(255,250,232,0.21)');
    halo.addColorStop(0.28, 'rgba(240,248,236,0.08)');
    halo.addColorStop(0.6, 'rgba(190,255,228,0.025)');
    halo.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = halo;
    ctx.fillRect(mx - r * 1.6, my - r * 1.6, r * 3.2, r * 3.2);
    ctx.globalCompositeOperation = 'source-over';
    if (this.moon.ready) {
      // the surface is drawn by moon.ts at the size it has on this screen
      const half = r / MOON_FILL;
      this.moon.update(half * 2 * this.dpr, t);
      ctx.drawImage(this.moon.canvas, mx - half, my - half, half * 2, half * 2);
    } else {
      // no WebGL: a plain lit disc
      const g = ctx.createRadialGradient(mx - r * 0.35, my - r * 0.3, r * 0.1, mx, my, r);
      g.addColorStop(0, '#dcdad2');
      g.addColorStop(0.7, '#9a9a9e');
      g.addColorStop(1, '#3a3d48');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(mx, my, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  private drawGrid(
    x: number,
    camY: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, w, h, u } = this;
    ctx.lineWidth = 1;
    ctx.strokeStyle = 'rgba(255,255,255,0.045)';
    ctx.fillStyle = 'rgba(255,255,255,0.26)';
    ctx.font = `${Math.max(9, Math.min(12, u * 0.2))}px ui-monospace, Menlo, Consolas, monospace`;
    ctx.textAlign = 'right';
    ctx.textBaseline = 'bottom';
    const yMin = Math.floor((camY - (h - this.baseY) / u) / 2) * 2;
    const yMax = camY + this.baseY / u;
    for (let y = yMin; y <= yMax; y += 2) {
      const py = Math.round(sy(y)) + 0.5;
      ctx.beginPath();
      ctx.moveTo(0, py);
      ctx.lineTo(w, py);
      ctx.stroke();
      // a made-up SNEK/ADA price scale: 3% per unit of height
      ctx.fillText((0.0045 * 1.03 ** y).toFixed(5), w - 6, py - 2);
    }
    const iMin = Math.floor((x - this.px / u) / 5) * 5;
    for (let i = iMin; sx(i) < w; i += 5) {
      const p = Math.round(sx(i)) + 0.5;
      ctx.beginPath();
      ctx.moveTo(p, 0);
      ctx.lineTo(p, h);
      ctx.stroke();
    }
  }

  private drawCandle(c: Candle, sx: (n: number) => number, sy: (n: number) => number): void {
    const { ctx, h, u } = this;
    const x0 = sx(c.i);
    if (c.gap) {
      // a liquidity gap: nothing to stand on, marked with red hatching
      ctx.save();
      ctx.beginPath();
      ctx.rect(x0, 0, u, h);
      ctx.clip();
      const g = ctx.createLinearGradient(0, sy(c.top), 0, h);
      g.addColorStop(0, 'rgba(255,77,94,0)');
      g.addColorStop(1, 'rgba(255,77,94,0.22)');
      ctx.fillStyle = g;
      ctx.fillRect(x0, sy(c.top), u, h - sy(c.top));
      ctx.strokeStyle = 'rgba(255,77,94,0.22)';
      ctx.lineWidth = 2;
      for (let y = sy(c.top) + u * 0.4; y < h + u; y += u * 0.45) {
        ctx.beginPath();
        ctx.moveTo(x0, y);
        ctx.lineTo(x0 + u, y - u * 0.5);
        ctx.stroke();
      }
      ctx.restore();
      return;
    }
    const top = sy(c.top);
    const bot = sy(c.bottom);
    const bx = x0 + u * 0.08;
    const bw = u * 0.84;
    const col = c.green ? GREEN : RED;
    // the ground under the body, so the chart reads as something to stand on
    ctx.fillStyle = c.green ? 'rgba(46,229,138,0.07)' : 'rgba(255,77,94,0.07)';
    ctx.fillRect(bx, bot, bw, h - bot);
    ctx.strokeStyle = col;
    ctx.globalAlpha = 0.75;
    ctx.lineWidth = Math.max(1.5, u * 0.035);
    ctx.beginPath();
    ctx.moveTo(x0 + u * 0.5, bot);
    ctx.lineTo(x0 + u * 0.5, sy(c.low));
    if (!c.spike) {
      ctx.moveTo(x0 + u * 0.5, top);
      ctx.lineTo(x0 + u * 0.5, sy(c.high));
    }
    ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.fillStyle = col;
    const r = Math.min(5, u * 0.09, (bot - top) / 2);
    ctx.beginPath();
    ctx.roundRect(bx, top, bw, bot - top, r);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.4)';
    ctx.beginPath();
    ctx.roundRect(bx, top, bw, Math.max(2, u * 0.055), [r, r, 0, 0]);
    ctx.fill();
  }

  /** a jagged bolt from (x0, y0) down to (x1, y1); `seed` fixes its shape */
  private bolt(x0: number, y0: number, x1: number, y1: number, seed: number, width: number): void {
    const { ctx, u } = this;
    const steps = Math.max(4, Math.round(Math.abs(y1 - y0) / (u * 0.7)));
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    for (let k = 1; k < steps; k++) {
      const f = k / steps;
      const jag = Math.sin(seed * 12.9898 + k * 78.233) * 43758.5453;
      const off = (jag - Math.floor(jag) - 0.5) * u * 0.9 * (1 - f * 0.6);
      ctx.lineTo(x0 + (x1 - x0) * f + off, y0 + (y1 - y0) * f);
    }
    ctx.lineTo(x1, y1);
    ctx.lineJoin = 'miter';
    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(255,214,120,0.55)';
    ctx.lineWidth = width * 3;
    ctx.stroke();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = width;
    ctx.stroke();
    ctx.lineCap = 'butt';
    ctx.lineJoin = 'round';
  }

  /** the sky of a wick storm: dark, with a bank of cloud along the top and lightning far away */
  private drawStorm(t: number, k: number): void {
    const { ctx, w, h, u } = this;
    ctx.fillStyle = `rgba(3,5,12,${0.5 * k})`;
    ctx.fillRect(0, 0, w, h);
    // far-off lightning, a few times every ten seconds
    const beat = t * 0.45;
    const p = beat - Math.floor(beat);
    if (p < 0.14) {
      const n = Math.floor(beat);
      const r = Math.sin(n * 91.7) * 9973;
      const x = (r - Math.floor(r)) * w;
      const fade = (1 - p / 0.14) * k;
      ctx.fillStyle = `rgba(190,210,255,${0.07 * fade})`;
      ctx.fillRect(0, 0, w, h);
      ctx.globalAlpha = 0.5 * fade;
      this.bolt(x, h * 0.08, x + u * 0.8, h * 0.42, n, Math.max(1, u * 0.03));
      ctx.globalAlpha = 1;
    }
    // the clouds the wicks come out of
    const n = Math.ceil(w / (u * 1.6)) + 1;
    for (let row = 0; row < 2; row++) {
      ctx.fillStyle = row ? `rgba(34,40,58,${0.9 * k})` : `rgba(22,26,40,${0.95 * k})`;
      for (let i = 0; i < n; i++) {
        const x = (i + (row ? 0.5 : 0)) * u * 1.6 + Math.sin(t * 0.25 + i * 1.7 + row) * u * 0.3;
        const y = h * (0.035 + row * 0.03) + Math.sin(i * 2.3 + row * 1.1) * u * 0.25;
        ctx.beginPath();
        ctx.arc(x, y, u * (1.05 + 0.3 * Math.sin(i * 1.3 + row * 2)), 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  /**
   * A wick of a wick storm. Until the player is WICK_STRIKE candles from it only its outline shows,
   * blinking; then it strikes its candle out of the sky like lightning, and stands there.
   */
  private drawStrike(
    c: Candle,
    run: Run,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u } = this;
    const x = sx(c.i + 0.5);
    const y0 = sy(c.top);
    const y1 = sy(c.top + c.spike);
    const due = c.i - WICK_STRIKE;
    if (run.x < due) {
      // where it will strike, and how tall it will stand
      const beat = 0.5 + 0.5 * Math.sin(t * 14 + c.i);
      ctx.setLineDash([u * 0.14, u * 0.16]);
      ctx.lineDashOffset = -t * u * 3;
      ctx.strokeStyle = `rgba(255,120,135,${0.25 + 0.2 * beat})`;
      ctx.lineWidth = Math.max(1.5, u * 0.035);
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, y1);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.lineCap = 'round';
      ctx.strokeStyle = `rgba(255,77,94,${0.22 + 0.25 * beat})`;
      ctx.lineWidth = u * (SPIKE_W + 0.12);
      ctx.beginPath();
      ctx.moveTo(x, y0);
      ctx.lineTo(x, y1);
      ctx.stroke();
      ctx.lineCap = 'butt';
      ctx.fillStyle = `rgba(255,77,94,${0.5 + 0.4 * beat})`;
      ctx.beginPath();
      ctx.moveTo(x, y1 - u * 0.2);
      ctx.lineTo(x + u * 0.16, y1 + u * 0.12);
      ctx.lineTo(x - u * 0.16, y1 + u * 0.12);
      ctx.closePath();
      ctx.fill();
      return;
    }
    let at = this.struck.get(c.i);
    if (at === undefined) {
      // (a wick first seen well after it struck just stands there)
      const fresh = run.x - due < 0.6;
      at = fresh ? t : -9;
      this.struck.set(c.i, at);
      if (fresh) {
        this.burst(c.i + 0.5, c.top + 0.1, '#ffe9ec', 14, 6);
        this.burst(c.i + 0.5, c.top + c.spike, '#ffd678', 8, 4);
        this.shakeBy(0.1);
        this.flashBy('#dfe9ff', 0.22);
      }
    }
    const age = t - at;
    if (age < 0.26) {
      ctx.globalAlpha = 1 - age / 0.26;
      this.bolt(x + u * 0.5, 0, x, y1, c.i, Math.max(2, u * 0.07));
      ctx.globalAlpha = 1;
    }
    this.drawSpike(c, t, sx, sy);
  }

  private drawSpike(
    c: Candle,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u } = this;
    const x = sx(c.i + 0.5);
    const y0 = sy(c.top);
    const y1 = sy(c.top + c.spike);
    const pulse = 0.7 + 0.3 * Math.sin(t * 9 + c.i);
    ctx.lineCap = 'round';
    ctx.strokeStyle = `rgba(255,77,94,${0.3 * pulse})`;
    ctx.lineWidth = u * (SPIKE_W + 0.2);
    ctx.beginPath();
    ctx.moveTo(x, y0);
    ctx.lineTo(x, y1);
    ctx.stroke();
    ctx.strokeStyle = '#ffe9ec';
    ctx.lineWidth = u * SPIKE_W * 0.6;
    ctx.beginPath();
    ctx.moveTo(x, y0);
    ctx.lineTo(x, y1 + u * 0.1);
    ctx.stroke();
    ctx.lineCap = 'butt';
    // the tip
    ctx.fillStyle = RED;
    ctx.beginPath();
    ctx.moveTo(x, y1 - u * 0.2);
    ctx.lineTo(x + u * 0.16, y1 + u * 0.12);
    ctx.lineTo(x - u * 0.16, y1 + u * 0.12);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#ffe9ec';
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }

  private drawFud(
    c: Candle,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u } = this;
    const x = sx(c.i + 0.5);
    const y = sy(c.top + c.fud);
    const r = FUD_R * u;
    const wob = Math.sin(t * 2.2 + c.i) * 0.04;
    const blobs: [number, number, number][] = [
      [-0.55, 0.12 + wob, 0.52],
      [0.55, 0.12 - wob, 0.52],
      [-0.15, -0.28, 0.6],
      [0.3, -0.2, 0.5],
      [0, 0.2, 0.55],
    ];
    ctx.strokeStyle = RED;
    ctx.lineWidth = Math.max(3, u * 0.09);
    for (const [dx, dy, k] of blobs) {
      ctx.beginPath();
      ctx.arc(x + dx * r, y + dy * r, k * r, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.fillStyle = '#3d0f18';
    for (const [dx, dy, k] of blobs) {
      ctx.beginPath();
      ctx.arc(x + dx * r, y + dy * r, k * r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = '#ffd5da';
    ctx.font = `900 ${u * 0.3}px ${FONT}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('FUD', x, y);
  }

  /** a bear: a short seller standing on the candle, facing the player */
  private drawBear(
    c: Candle,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { u } = this;
    const bob = Math.abs(Math.sin(t * 5 + c.i)) * u * 0.04;
    this.bearShape(sx(c.i + 0.5), sy(c.top) - bob, BEAR_HALF_W * u, BEAR_H * u);
  }

  /** where a jet is drawn: the screen x of its middle and the screen y of its underside */
  private jetAt(
    c: Candle,
    run: Run,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): [x: number, y: number] {
    const chart = run.chart;
    const fx = flyerX(c.i, run.x);
    // it keeps its height over whatever ground it crosses on the way in; where it meets the player
    // the ground is flat, so there this is exactly the height the rules use
    const topAt = (j: number) => chart.solidUpTo(Math.max(0, j)).top;
    const a = Math.floor(fx - 0.5);
    const k = fx - 0.5 - a;
    const ground = Math.max(c.top, topAt(a) * (1 - k) + topAt(a + 1) * k);
    return [sx(fx), sy(ground + c.flyer)];
  }

  /** a blinking arrow on the right edge: something is coming in at this height */
  private drawIncoming(y: number, t: number, color: string, size = 1): void {
    const { ctx, u, w } = this;
    const ax = w - u * 0.5;
    const beat = 0.5 + 0.5 * Math.sin(t * 16);
    const r = u * (0.4 + 0.06 * beat) * size;
    ctx.globalAlpha = 0.25 + 0.2 * beat;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(ax, y, r * 1.7, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 0.75 + 0.25 * beat;
    ctx.strokeStyle = '#ffe9ec';
    ctx.lineWidth = Math.max(2, u * 0.06);
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(ax - r, y);
    ctx.lineTo(ax + r * 0.75, y - r * 0.9);
    ctx.lineTo(ax + r * 0.3, y);
    ctx.lineTo(ax + r * 0.75, y + r * 0.9);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  /**
   * A fighter jet of the shorts' air force, flying in from the right. While it is still beyond the
   * right edge, a red arrow on that edge shows the height it will come in at. A bomber carries its
   * bomb under the belly until it lets go.
   */
  private drawFlyer(
    c: Candle,
    run: Run,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u, w } = this;
    const [x, feet] = this.jetAt(c, run, sx, sy);
    const bh = FLYER_H * u;
    if (x - u * 0.9 > w) {
      this.drawIncoming(feet - bh / 2, t, '#ff5c6c');
      return;
    }
    const y = feet - bh / 2 + Math.sin(t * 7 + c.i * 1.3) * u * 0.03;
    const s = u * (FLYER_HALF_W / 0.45);
    ctx.lineJoin = 'round';
    // vapour trails off the wing and the tail (it flies to the left)
    ctx.strokeStyle = 'rgba(255,233,236,0.4)';
    ctx.lineWidth = Math.max(1.5, u * 0.035);
    ctx.lineCap = 'round';
    for (const [dy, len, off] of [
      [-0.2, 0.7, 0],
      [0.24, 0.9, 0.45],
    ]) {
      const slide = ((t * 3 + off + c.i * 0.37) % 1) * s * 0.25;
      ctx.beginPath();
      ctx.moveTo(x + s * 0.6 + slide, y + s * dy);
      ctx.lineTo(x + s * (0.6 + len) + slide, y + s * dy);
      ctx.stroke();
    }
    ctx.lineCap = 'butt';
    // the flame of the engine
    const burn = 0.75 + 0.25 * Math.sin(t * 40 + c.i);
    ctx.fillStyle = '#ffb347';
    ctx.beginPath();
    ctx.moveTo(x + s * 0.44, y - s * 0.06);
    ctx.lineTo(x + s * (0.5 + 0.34 * burn), y + s * 0.005);
    ctx.lineTo(x + s * 0.44, y + s * 0.07);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#fff3c4';
    ctx.beginPath();
    ctx.moveTo(x + s * 0.44, y - s * 0.03);
    ctx.lineTo(x + s * (0.48 + 0.16 * burn), y + s * 0.005);
    ctx.lineTo(x + s * 0.44, y + s * 0.04);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(2, u * 0.045);
    // a bomber's bomb, slung under the belly until it is dropped
    const squad = c.squad;
    if (squad === 'bomber') {
      let hole = c.i + 1;
      while (!run.chart.at(hole).crater && hole < c.i + 8) hole++;
      if (run.x < hole - BOMB_NOTICE - BOMB_FALL)
        this.bombShape(x + s * 0.08, y + s * 0.24, 0, s * 0.8);
    }
    // the far tailplane and the wing, behind the body
    ctx.fillStyle = '#7d1622';
    ctx.beginPath();
    ctx.moveTo(x + s * 0.26, y + s * 0.02);
    ctx.lineTo(x + s * 0.5, y + s * 0.16);
    ctx.lineTo(x + s * 0.56, y + s * 0.16);
    ctx.lineTo(x + s * 0.44, y + s * 0.02);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // the tail fin
    ctx.fillStyle = '#c9303f';
    ctx.beginPath();
    ctx.moveTo(x + s * 0.14, y - s * 0.08);
    ctx.lineTo(x + s * 0.4, y - s * 0.31);
    ctx.lineTo(x + s * 0.5, y - s * 0.31);
    ctx.lineTo(x + s * 0.45, y - s * 0.06);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // the body: a pointed nose on the left, the engine on the right
    ctx.beginPath();
    ctx.moveTo(x - s * 0.58, y + s * 0.02);
    ctx.quadraticCurveTo(x - s * 0.3, y - s * 0.1, x - s * 0.02, y - s * 0.11);
    ctx.lineTo(x + s * 0.38, y - s * 0.09);
    ctx.lineTo(x + s * 0.46, y - s * 0.06);
    ctx.lineTo(x + s * 0.46, y + s * 0.07);
    ctx.lineTo(x + s * 0.2, y + s * 0.1);
    ctx.quadraticCurveTo(x - s * 0.25, y + s * 0.12, x - s * 0.58, y + s * 0.02);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // the near wing, swept back
    ctx.fillStyle = '#a82436';
    ctx.beginPath();
    ctx.moveTo(x - s * 0.12, y + s * 0.03);
    ctx.lineTo(x + s * 0.26, y + s * 0.3);
    ctx.lineTo(x + s * 0.4, y + s * 0.3);
    ctx.lineTo(x + s * 0.24, y + s * 0.04);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // the canopy
    ctx.fillStyle = '#9fe0ff';
    ctx.beginPath();
    ctx.moveTo(x - s * 0.36, y - s * 0.055);
    ctx.quadraticCurveTo(x - s * 0.2, y - s * 0.24, x - s * 0.02, y - s * 0.11);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // the short sign on the tail: a down arrow
    ctx.fillStyle = '#ffe9ec';
    ctx.beginPath();
    ctx.moveTo(x + s * 0.33, y - s * 0.24);
    ctx.lineTo(x + s * 0.45, y - s * 0.24);
    ctx.lineTo(x + s * 0.39, y - s * 0.13);
    ctx.closePath();
    ctx.fill();
    // the nose cone
    ctx.fillStyle = INK;
    ctx.beginPath();
    ctx.moveTo(x - s * 0.58, y + s * 0.02);
    ctx.lineTo(x - s * 0.46, y - s * 0.035);
    ctx.lineTo(x - s * 0.46, y + s * 0.06);
    ctx.closePath();
    ctx.fill();
  }

  /** a bomb with its nose pointing along `angle` (0 = to the left), `s` pixels long */
  private bombShape(x: number, y: number, angle: number, s: number): void {
    const { ctx, u } = this;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.lineJoin = 'round';
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(1.5, u * 0.035);
    // the fins
    ctx.fillStyle = '#c9303f';
    ctx.beginPath();
    ctx.moveTo(s * 0.12, 0);
    ctx.lineTo(s * 0.34, -s * 0.16);
    ctx.lineTo(s * 0.34, s * 0.16);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#2a3140';
    ctx.beginPath();
    ctx.ellipse(-s * 0.05, 0, s * 0.27, s * 0.12, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#ff5c6c';
    ctx.beginPath();
    ctx.ellipse(-s * 0.24, 0, s * 0.07, s * 0.08, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  /**
   * A gunner's bullet. Before the shot, a sight line from the jet's nose shows where it will go;
   * after it, a tracer comes down at the player, and a yellow arrow shows it while it is still
   * beyond the right edge.
   */
  private drawBullet(
    c: Candle,
    run: Run,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u, w } = this;
    const jet = run.chart.at(c.i + c.bullet);
    const lead = c.i + 0.5 - run.x;
    const ahead = bulletX(c.i, run.x) - run.x;
    const [jx, jy] = this.jetAt(jet, run, sx, sy);
    const nose: [number, number] = [jx - u * 0.58, jy - (FLYER_H / 2) * u + u * 0.02];
    if (lead > fireLead(c.bullet)) {
      // not fired yet: the sight line, or an arrow low on the edge while the jet is out of sight
      if (jx - u * 0.9 > w) {
        this.drawIncoming(sy(c.top + BULLET_Y), t, '#ffd23f', 0.7);
        return;
      }
      // (the line points at where the bullet will be when it reaches the player)
      const tx = sx(run.x + 0.3);
      const ty = sy(c.top + BULLET_Y);
      ctx.globalAlpha = 0.45 + 0.35 * Math.sin(t * 20);
      ctx.strokeStyle = '#ffd23f';
      ctx.lineWidth = Math.max(1.5, u * 0.03);
      ctx.setLineDash([u * 0.12, u * 0.12]);
      ctx.lineDashOffset = t * u * 2;
      ctx.beginPath();
      ctx.moveTo(nose[0], nose[1]);
      ctx.lineTo(tx, ty);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 1;
      return;
    }
    const alt = bulletAlt(c.bullet, ahead);
    if (alt <= 0.02) {
      // into the ground behind the player
      if (!this.spent.has(c.i)) {
        this.spent.add(c.i);
        this.burst(run.x + ahead, c.top + 0.05, '#c9b8a0', 8, 3);
      }
      return;
    }
    const x = sx(run.x + ahead);
    const y = sy(c.top + alt);
    if (x - u * 0.4 > w) {
      this.drawIncoming(y, t, '#ffd23f', 0.7);
      return;
    }
    // the flash at the nose, just after the shot
    const since = fireLead(c.bullet) - lead;
    if (since < 0.5 && jx - u * 0.9 <= w) {
      ctx.globalAlpha = 1 - since / 0.5;
      ctx.fillStyle = '#fff3c4';
      ctx.beginPath();
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2;
        const r = u * (k % 2 ? 0.1 : 0.26);
        ctx.lineTo(nose[0] + Math.cos(a) * r, nose[1] + Math.sin(a) * r);
      }
      ctx.closePath();
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    // the tracer: it flies down and to the left, along the line from the jet's nose
    const slope = (bulletAlt(c.bullet, 1) - bulletAlt(c.bullet, 0)) * 1;
    const len = Math.hypot(1, slope);
    const dx = (1 / len) * u;
    const dy = (-slope / len) * u;
    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(255,92,108,0.55)';
    ctx.lineWidth = Math.max(4, u * 0.16);
    ctx.beginPath();
    ctx.moveTo(x - dx * BULLET_HALF_W, y - dy * BULLET_HALF_W);
    ctx.lineTo(x + dx * 0.9, y + dy * 0.9);
    ctx.stroke();
    ctx.strokeStyle = '#ffd23f';
    ctx.lineWidth = Math.max(2.5, u * 0.09);
    ctx.beginPath();
    ctx.moveTo(x - dx * BULLET_HALF_W, y - dy * BULLET_HALF_W);
    ctx.lineTo(x + dx * 0.45, y + dy * 0.45);
    ctx.stroke();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = Math.max(1.5, u * 0.045);
    ctx.beginPath();
    ctx.moveTo(x - dx * BULLET_HALF_W, y - dy * BULLET_HALF_W);
    ctx.lineTo(x + dx * 0.1, y + dy * 0.1);
    ctx.stroke();
    ctx.lineCap = 'butt';
  }

  /**
   * A bombed gap, drawn from its first candle: the target mark while the candles still stand, the
   * bomb on its way down from the bomber, the blast, and the smoke over the gap afterwards.
   */
  private drawBombing(
    c: Candle,
    run: Run,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u } = this;
    const chart = run.chart;
    const width = chart.at(c.i + 1).crater ? 2 : 1;
    const mid = c.i + width / 2;
    const land = c.i - BOMB_NOTICE;
    const x = sx(mid);
    const ground = sy(c.top);
    if (run.x >= land) {
      if (!this.bombed.has(c.i)) {
        this.bombed.add(c.i);
        this.burst(mid, c.top + 0.2, '#ffb347', 34, 9);
        this.burst(mid, c.top + 0.2, '#ff5c6c', 22, 7);
        this.burst(mid, c.top - 0.3, c.green ? GREEN : RED, 18, 6, 22);
        this.shakeBy(0.22);
        this.flashBy('#ffb347', 0.35);
      }
      // smoke out of the hole
      for (let k = 0; k < 5; k++) {
        const p = (t * 0.55 + k / 5 + c.i * 0.13) % 1;
        ctx.globalAlpha = 0.3 * (1 - p);
        ctx.fillStyle = '#8f98a8';
        ctx.beginPath();
        ctx.arc(
          x + Math.sin(k * 2.4 + p * 3) * u * 0.3 * width,
          ground - p * u * 1.5,
          u * (0.16 + 0.22 * p),
          0,
          Math.PI * 2,
        );
        ctx.fill();
      }
      ctx.globalAlpha = 1;
      return;
    }
    // the candles still stand: a blinking target on them
    const beat = 0.5 + 0.5 * Math.sin(t * 14);
    const r = u * (0.3 + 0.05 * beat);
    const ty = ground - u * 0.05;
    ctx.globalAlpha = 0.6 + 0.4 * beat;
    ctx.strokeStyle = '#ff5c6c';
    ctx.lineWidth = Math.max(2, u * 0.055);
    ctx.beginPath();
    ctx.arc(x, ty, r, 0, Math.PI * 2);
    ctx.moveTo(x - r * 1.5, ty);
    ctx.lineTo(x - r * 0.5, ty);
    ctx.moveTo(x + r * 0.5, ty);
    ctx.lineTo(x + r * 1.5, ty);
    ctx.moveTo(x, ty - r * 1.5);
    ctx.lineTo(x, ty - r * 0.5);
    ctx.moveTo(x, ty + r * 0.5);
    ctx.lineTo(x, ty + r * 1.5);
    ctx.stroke();
    ctx.globalAlpha = 1;
    // the bomb, from the bomber's belly down onto the target
    const from = land - BOMB_FALL;
    if (run.x < from) return;
    let m = c.i - 1;
    while (m > c.i - 8 && chart.at(m).squad !== 'bomber') m--;
    const jet = chart.at(m);
    const x0 = flyerX(m, from);
    const y0 = jet.top + jet.flyer + 0.05;
    const k = (run.x - from) / BOMB_FALL;
    const bx = x0 + (mid - x0) * k;
    const by = y0 + (c.top - y0) * k * k;
    // (on the screen it also drifts left with the chart)
    const vx = (mid - x0) / BOMB_FALL - 1;
    const vy = ((c.top - y0) * 2 * k) / BOMB_FALL;
    this.bombShape(sx(bx), sy(by), Math.atan2(-vy, vx) + Math.PI, u * 0.95);
  }

  /** the big bear at the end of a bear market: it lies across two candles, and its head is the target */
  private drawBoss(
    c: Candle,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u } = this;
    const x = sx(c.i + BOSS_W / 2);
    const y = sy(c.top);
    const bw = (BOSS_W / 2 - 0.08) * u;
    const bh = BOSS_H * u;
    // a red glow, so it reads as the boss
    ctx.globalAlpha = 0.2 + 0.07 * Math.sin(t * 5);
    ctx.fillStyle = RED;
    ctx.beginPath();
    ctx.ellipse(x, y - bh * 0.5, bw * 1.5, bh * 0.85, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
    this.bearShape(x, y - Math.abs(Math.sin(t * 3)) * u * 0.05, bw, bh);
    // land here
    const ay = y - bh - u * (0.55 + 0.12 * Math.sin(t * 7));
    ctx.fillStyle = GOLD;
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(2, u * 0.05);
    ctx.beginPath();
    ctx.moveTo(x - u * 0.26, ay - u * 0.3);
    ctx.lineTo(x + u * 0.26, ay - u * 0.3);
    ctx.lineTo(x, ay + u * 0.08);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }

  /**
   * A paw of the big bear, hanging over `width` candles from an arm that comes down out of the sky.
   * Whoever stays low passes under it; once the player is past, it comes down behind them.
   */
  private drawPaw(
    c: Candle,
    width: number,
    run: Run,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u } = this;
    const x = sx(c.i + width / 2);
    const ground = sy(c.top);
    const half = width * u * 0.5 * 0.96;
    // how far it has come down: 0 = hanging, 1 = on the ground
    const down = clamp((run.x - (c.i + width + 0.25)) / 0.5, 0, 1);
    if (down >= 1 && !this.slammed.has(c.i)) {
      this.slammed.add(c.i);
      this.shakeBy(0.16);
      this.burst(c.i + width / 2, c.top + 0.1, '#c9b8a0', 16, 5);
    }
    const hang = (PAW_FLOOR + 0.85) * u;
    const bottom =
      ground - hang * (1 - down * down) + Math.sin(t * 9 + c.i) * u * 0.03 * (1 - down);
    const palmH = u * 0.95;
    const top = bottom - palmH;
    // the way through: a low gold arc under the paw, from one edge of the crack to the other
    ctx.globalAlpha = 0.75 * (1 - down);
    ctx.strokeStyle = GOLD;
    ctx.lineWidth = Math.max(2, u * 0.06);
    ctx.setLineDash([u * 0.16, u * 0.14]);
    ctx.lineDashOffset = -t * u * 1.6;
    ctx.beginPath();
    ctx.moveTo(x - half - u * 0.45, ground - u * 0.25);
    ctx.quadraticCurveTo(x, ground - u * 1.5, x + half + u * 0.45, ground - u * 0.25);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;
    ctx.lineJoin = 'round';
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(2, u * 0.05);
    // the arm
    ctx.fillStyle = '#a82436';
    ctx.beginPath();
    ctx.rect(x - half * 0.62, -u, half * 1.24, top + u + palmH * 0.3);
    ctx.fill();
    ctx.stroke();
    // the paw
    ctx.fillStyle = '#c9303f';
    ctx.beginPath();
    ctx.roundRect(x - half, top, half * 2, palmH, [u * 0.3, u * 0.3, u * 0.4, u * 0.4]);
    ctx.fill();
    ctx.stroke();
    // the pad
    ctx.fillStyle = '#ffb8c0';
    ctx.beginPath();
    ctx.ellipse(x, top + palmH * 0.42, half * 0.5, palmH * 0.22, 0, 0, Math.PI * 2);
    ctx.fill();
    // toes and claws along the bottom edge
    const toes = width > 1 ? 4 : 3;
    for (let k = 0; k < toes; k++) {
      const tx = x - half + ((k + 0.5) * half * 2) / toes;
      ctx.fillStyle = '#ffb8c0';
      ctx.beginPath();
      ctx.ellipse(tx, bottom - palmH * 0.2, half * 0.16, palmH * 0.1, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffe9ec';
      ctx.beginPath();
      ctx.moveTo(tx - u * 0.09, bottom - u * 0.04);
      ctx.lineTo(tx + u * 0.09, bottom - u * 0.04);
      ctx.lineTo(tx, bottom + u * 0.24);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
  }

  /**
   * The bull, side on and at full gallop, with its feet at (x, y). The rider sits on its back.
   */
  private drawBull(x: number, y: number, t: number, alpha: number): void {
    const { ctx } = this;
    // drawn in units of its own: its back is BULL_BACK candles above the ground
    const u = (this.u * BULL_BACK) / 1.05;
    const body = '#22b573';
    const dark = '#15814f';
    ctx.save();
    ctx.translate(x, y);
    ctx.globalAlpha = alpha;
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.strokeStyle = INK;
    // speed lines behind it
    ctx.lineWidth = Math.max(2, u * 0.05);
    ctx.strokeStyle = 'rgba(255,194,31,0.55)';
    for (let k = 0; k < 3; k++) {
      const ly = -u * (0.35 + k * 0.33);
      const lx = -u * (1.7 + ((t * 7 + k * 0.37) % 1) * 0.9);
      ctx.beginPath();
      ctx.moveTo(lx, ly);
      ctx.lineTo(lx - u * 0.6, ly);
      ctx.stroke();
    }
    ctx.strokeStyle = INK;
    // legs, galloping: the far pair first, darker
    const leg = (hx: number, phase: number, colour: string) => {
      const a = Math.sin(t * 24 + phase) * 0.75;
      ctx.save();
      ctx.translate(hx, -u * 0.5);
      ctx.rotate(a);
      ctx.fillStyle = colour;
      ctx.beginPath();
      ctx.roundRect(-u * 0.09, 0, u * 0.18, u * 0.5, u * 0.07);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = GOLD;
      ctx.beginPath();
      ctx.roundRect(-u * 0.1, u * 0.4, u * 0.2, u * 0.12, u * 0.04);
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    };
    ctx.lineWidth = Math.max(1.5, u * 0.04);
    leg(-u * 0.62, 0.6, dark);
    leg(u * 0.62, 3.7, dark);
    // tail
    ctx.lineWidth = Math.max(2, u * 0.07);
    ctx.strokeStyle = dark;
    ctx.beginPath();
    ctx.moveTo(-u * 1.0, -u * 0.85);
    ctx.quadraticCurveTo(-u * 1.35, -u * 1.0, -u * 1.45, -u * (1.3 + 0.08 * Math.sin(t * 12)));
    ctx.stroke();
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(2, u * 0.05);
    // body, with a big shoulder hump
    ctx.fillStyle = body;
    ctx.beginPath();
    ctx.moveTo(-u * 1.08, -u * 0.72);
    ctx.quadraticCurveTo(-u * 1.05, -u * 1.08, -u * 0.5, -u * 1.06);
    ctx.lineTo(u * 0.2, -u * 1.06);
    ctx.quadraticCurveTo(u * 0.75, -u * 1.42, u * 1.0, -u * 0.95);
    ctx.quadraticCurveTo(u * 1.02, -u * 0.5, u * 0.55, -u * 0.42);
    ctx.lineTo(-u * 0.7, -u * 0.42);
    ctx.quadraticCurveTo(-u * 1.1, -u * 0.42, -u * 1.08, -u * 0.72);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // belly shade
    ctx.fillStyle = dark;
    ctx.beginPath();
    ctx.ellipse(-u * 0.1, -u * 0.47, u * 0.62, u * 0.08, 0, 0, Math.PI * 2);
    ctx.fill();
    // the near legs
    ctx.lineWidth = Math.max(1.5, u * 0.04);
    leg(-u * 0.78, 2.2, body);
    leg(u * 0.46, 5.3, body);
    ctx.lineWidth = Math.max(2, u * 0.05);
    // head, lowered to charge
    ctx.fillStyle = body;
    ctx.beginPath();
    ctx.moveTo(u * 0.85, -u * 1.08);
    ctx.quadraticCurveTo(u * 1.3, -u * 1.2, u * 1.5, -u * 0.9);
    ctx.quadraticCurveTo(u * 1.72, -u * 0.62, u * 1.5, -u * 0.48);
    ctx.quadraticCurveTo(u * 1.15, -u * 0.4, u * 0.9, -u * 0.62);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // muzzle and nose ring
    ctx.fillStyle = '#c8f5dd';
    ctx.beginPath();
    ctx.ellipse(u * 1.5, -u * 0.62, u * 0.17, u * 0.14, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = INK;
    ctx.beginPath();
    ctx.arc(u * 1.57, -u * 0.66, Math.max(1, u * 0.03), 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = GOLD;
    ctx.lineWidth = Math.max(2, u * 0.045);
    ctx.beginPath();
    ctx.arc(u * 1.55, -u * 0.5, u * 0.09, 0.2, Math.PI - 0.2);
    ctx.stroke();
    // an angry eye
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(1.5, u * 0.04);
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.ellipse(u * 1.22, -u * 0.86, u * 0.09, u * 0.07, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = INK;
    ctx.beginPath();
    ctx.arc(u * 1.25, -u * 0.85, Math.max(1, u * 0.04), 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(u * 1.08, -u * 1.0);
    ctx.lineTo(u * 1.36, -u * 0.9);
    ctx.stroke();
    // horns: gold, pointing forward and up
    ctx.fillStyle = GOLD;
    ctx.lineWidth = Math.max(1.5, u * 0.04);
    ctx.beginPath();
    ctx.moveTo(u * 0.95, -u * 1.1);
    ctx.quadraticCurveTo(u * 1.35, -u * 1.25, u * 1.62, -u * 1.62);
    ctx.quadraticCurveTo(u * 1.25, -u * 1.5, u * 1.1, -u * 1.16);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // steam from the nostrils
    ctx.fillStyle = '#ffffff';
    for (let k = 0; k < 3; k++) {
      const f = (t * 2.4 + k / 3) % 1;
      ctx.globalAlpha = alpha * 0.6 * (1 - f);
      ctx.beginPath();
      ctx.arc(u * (1.66 - f * 0.5), -u * (0.62 - f * 0.25), u * (0.05 + 0.09 * f), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  /** the shape of a bear whose feet are at (x, y): `bw` = half its width, `bh` = its height, in pixels */
  private bearShape(x: number, y: number, bw: number, bh: number): void {
    const { ctx, u } = this;
    ctx.lineWidth = Math.max(2, u * 0.05);
    ctx.strokeStyle = INK;
    ctx.fillStyle = '#c9303f';
    // ears
    for (const dx of [-0.62, 0.62]) {
      ctx.beginPath();
      ctx.arc(x + dx * bw, y - bh * 0.9, bw * 0.3, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
    // body and head in one rounded shape
    ctx.beginPath();
    ctx.roundRect(x - bw, y - bh * 0.95, bw * 2, bh * 0.95, [
      bw * 0.9,
      bw * 0.9,
      bw * 0.35,
      bw * 0.35,
    ]);
    ctx.fill();
    ctx.stroke();
    // belly with the short sign: a down arrow
    ctx.fillStyle = '#7d1622';
    ctx.beginPath();
    ctx.ellipse(x, y - bh * 0.2, bw * 0.55, bh * 0.17, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#ffe9ec';
    ctx.beginPath();
    ctx.moveTo(x - bw * 0.26, y - bh * 0.28);
    ctx.lineTo(x + bw * 0.26, y - bh * 0.28);
    ctx.lineTo(x, y - bh * 0.1);
    ctx.closePath();
    ctx.fill();
    // snout
    const fx = x - bw * 0.22;
    ctx.fillStyle = '#ffb8c0';
    ctx.beginPath();
    ctx.ellipse(fx, y - bh * 0.5, bw * 0.4, bh * 0.13, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = INK;
    ctx.beginPath();
    ctx.ellipse(fx - bw * 0.1, y - bh * 0.54, bw * 0.13, bh * 0.05, 0, 0, Math.PI * 2);
    ctx.fill();
    // angry eyes
    ctx.lineWidth = Math.max(1.5, u * 0.035);
    for (const side of [-1, 1]) {
      const ex = fx + side * bw * 0.36;
      ctx.beginPath();
      ctx.arc(ex, y - bh * 0.7, bw * 0.09, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(ex - side * bw * 0.22, y - bh * 0.76);
      ctx.lineTo(ex + side * bw * 0.16, y - bh * 0.86);
      ctx.stroke();
    }
  }

  /**
   * The whale that ate the liquidity: it lies in the water between the two banks. `c` is the candle
   * of its blowhole, in the middle of its back; the back is level with that candle's top.
   */
  private drawWhale(
    c: Candle,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, h, u } = this;
    const half = WHALE_BACK / 2;
    // c is the blowhole candle; the middle of the whale is the middle of its back
    const mid = c.i - WHALE_BLOWHOLE + half;
    const cx = sx(mid);
    /** the blowhole, towards the head */
    const bx = sx(c.i + 0.5);
    const yB = sy(c.top);
    const x0 = sx(mid - half - 1);
    const x1 = sx(mid + half + 1);
    const yW = yB + u * 0.85;
    const L = half * u;
    const navy = '#16324f';

    // deep water behind the whale
    const deep = ctx.createLinearGradient(0, yW, 0, h);
    deep.addColorStop(0, '#0f3a66');
    deep.addColorStop(1, '#061627');
    ctx.fillStyle = deep;
    ctx.fillRect(x0, yW, x1 - x0, h - yW);

    ctx.save();
    ctx.beginPath();
    ctx.rect(x0 - u * 0.1, 0, x1 - x0 + u * 0.2, h);
    ctx.clip();
    ctx.lineJoin = 'round';
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(2, u * 0.05);

    // tail flukes, lifted out of the water behind it
    const wag = Math.sin(t * 2.4) * 0.12;
    ctx.save();
    ctx.translate(cx - L - u * 0.15, yB + u * 0.75);
    ctx.rotate(-0.5 + wag);
    ctx.fillStyle = navy;
    ctx.beginPath();
    ctx.moveTo(u * 0.25, u * 0.1);
    ctx.quadraticCurveTo(-u * 0.2, -u * 0.1, -u * 0.55, -u * 0.75);
    ctx.quadraticCurveTo(-u * 0.5, -u * 0.25, -u * 0.72, -u * 0.05);
    ctx.quadraticCurveTo(-u * 0.5, u * 0.02, -u * 0.95, u * 0.45);
    ctx.quadraticCurveTo(-u * 0.3, u * 0.35, u * 0.25, u * 0.1);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();

    // the body: a long flat back, a blunt head on the right
    ctx.fillStyle = navy;
    ctx.beginPath();
    ctx.moveTo(cx - L - u * 0.35, yB + u * 1.1);
    ctx.quadraticCurveTo(cx - L - u * 0.1, yB + u * 0.1, cx - L + u * 0.45, yB);
    ctx.lineTo(cx + L - u * 0.55, yB);
    ctx.quadraticCurveTo(cx + L + u * 0.3, yB + u * 0.05, cx + L + u * 0.32, yB + u * 0.9);
    ctx.lineTo(cx + L + u * 0.2, yB + u * 2.4);
    ctx.lineTo(cx - L - u * 0.35, yB + u * 2.4);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // light catching the back
    ctx.strokeStyle = '#4f8fc4';
    ctx.lineWidth = Math.max(2, u * 0.07);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(cx - L + u * 0.55, yB + u * 0.09);
    ctx.lineTo(cx + L - u * 0.7, yB + u * 0.09);
    ctx.stroke();
    // scars and barnacles
    ctx.strokeStyle = 'rgba(190,215,235,0.35)';
    ctx.lineWidth = Math.max(1, u * 0.025);
    for (const [dx, len] of [
      [-1.6, 0.5],
      [-0.9, 0.3],
      [0.9, 0.45],
    ]) {
      ctx.beginPath();
      ctx.moveTo(cx + dx * u, yB + u * 0.32);
      ctx.lineTo(cx + (dx + len) * u, yB + u * 0.42);
      ctx.stroke();
    }
    // the eye, small and low on the head
    ctx.fillStyle = '#e8f3ff';
    ctx.beginPath();
    ctx.arc(cx + L - u * 0.15, yB + u * 0.52, Math.max(2, u * 0.075), 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = INK;
    ctx.beginPath();
    ctx.arc(cx + L - u * 0.13, yB + u * 0.53, Math.max(1, u * 0.04), 0, Math.PI * 2);
    ctx.fill();

    // the blowhole and its spout: this is the spot that throws the player highest
    ctx.fillStyle = '#081a2c';
    ctx.beginPath();
    ctx.ellipse(bx, yB + u * 0.05, u * 0.2, u * 0.06, 0, 0, Math.PI * 2);
    ctx.fill();
    // a fountain as wide as the spot that launches: a tall jet with a shorter one on each side
    for (let d = -SPOUT_HALF; d <= SPOUT_HALF; d++) {
      const jx = bx + d * u;
      const jet = u * (d === 0 ? 2.6 : 1.7) * (1 + 0.13 * Math.sin(t * 7 + d * 1.9));
      const grad = ctx.createLinearGradient(0, yB, 0, yB - jet);
      grad.addColorStop(0, 'rgba(160,215,255,0.85)');
      grad.addColorStop(1, 'rgba(160,215,255,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(jx - u * 0.12, yB);
      ctx.quadraticCurveTo(jx - u * 0.2, yB - jet * 0.6, jx - u * 0.5, yB - jet);
      ctx.lineTo(jx + u * 0.5, yB - jet);
      ctx.quadraticCurveTo(jx + u * 0.2, yB - jet * 0.6, jx + u * 0.12, yB);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = '#dff1ff';
      for (let k = 0; k < 6; k++) {
        const f = (t * 1.3 + k / 6 + d * 0.31 + 1) % 1;
        const side = k % 2 ? 1 : -1;
        ctx.globalAlpha = 1 - f;
        ctx.beginPath();
        ctx.arc(
          jx + side * u * (0.08 + 0.4 * f) * (0.6 + 0.4 * Math.sin(k * 2.1)),
          yB - jet * f,
          Math.max(1.5, u * 0.05),
          0,
          Math.PI * 2,
        );
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }
    // "land here": a gold bar along the launching part of the back, and arrows pointing down at it
    const zone = (SPOUT_HALF + 0.5) * u - u * 0.12;
    const pulse = 0.6 + 0.4 * Math.sin(t * 6);
    ctx.strokeStyle = GOLD;
    ctx.globalAlpha = 0.45 + 0.5 * pulse;
    ctx.lineWidth = Math.max(3, u * 0.1);
    ctx.beginPath();
    ctx.moveTo(bx - zone, yB + u * 0.03);
    ctx.lineTo(bx + zone, yB + u * 0.03);
    ctx.stroke();
    ctx.fillStyle = GOLD;
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(1.5, u * 0.04);
    ctx.lineJoin = 'round';
    ctx.globalAlpha = 1;
    for (const d of [-SPOUT_HALF, SPOUT_HALF]) {
      const ax = bx + d * u * 0.5;
      const ay = yB - u * (0.5 + 0.12 * Math.sin(t * 6 + d));
      ctx.beginPath();
      ctx.moveTo(ax - u * 0.2, ay - u * 0.24);
      ctx.lineTo(ax + u * 0.2, ay - u * 0.24);
      ctx.lineTo(ax, ay);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
    ctx.lineCap = 'butt';

    // the water in front: everything below the surface is seen through it
    const front = ctx.createLinearGradient(0, yW, 0, yW + u * 2.2);
    front.addColorStop(0, 'rgba(40,120,200,0.45)');
    front.addColorStop(1, 'rgba(6,22,39,0.95)');
    ctx.fillStyle = front;
    ctx.fillRect(x0, yW, x1 - x0, h - yW);
    // the surface
    ctx.strokeStyle = 'rgba(190,230,255,0.8)';
    ctx.lineWidth = Math.max(1.5, u * 0.04);
    ctx.beginPath();
    for (let x = x0; x <= x1 + 1; x += u * 0.2) {
      const y = yW + Math.sin(x / (u * 0.35) + t * 3) * u * 0.035;
      if (x === x0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
  }

  private drawGate(
    c: Candle,
    run: Run,
    t: number,
    sx: (n: number) => number,
    sy: (n: number) => number,
  ): void {
    const { ctx, u } = this;
    const x = sx(c.i + 0.5);
    const y0 = sy(c.top);
    const y1 = sy(c.top + GATE_HEIGHT);
    const half = u * 0.42;
    const passed = run.x > c.i + 0.5;
    ctx.save();
    ctx.globalAlpha = passed ? 0.22 : 1;
    // under the arch: take profit
    const g = ctx.createLinearGradient(0, y1 - half, 0, y0);
    g.addColorStop(0, `rgba(255,194,31,${0.3 + 0.12 * Math.sin(t * 5)})`);
    g.addColorStop(1, 'rgba(255,194,31,0.04)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(x - half, y0);
    ctx.lineTo(x - half, y1);
    ctx.arc(x, y1, half, Math.PI, 0);
    ctx.lineTo(x + half, y0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = GOLD;
    ctx.lineWidth = Math.max(3, u * 0.09);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x - half, y0);
    ctx.lineTo(x - half, y1);
    ctx.arc(x, y1, half, Math.PI, 0);
    ctx.lineTo(x + half, y0);
    ctx.stroke();
    ctx.lineCap = 'butt';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `900 ${u * 0.3}px ${FONT}`;
    ctx.lineWidth = 4;
    ctx.strokeStyle = INK;
    ctx.fillStyle = GOLD;
    ctx.strokeText(this.labels.gate, x, y1 + u * 0.05);
    ctx.fillText(this.labels.gate, x, y1 + u * 0.05);
    // over the arch: keep holding, leverage up
    if (!passed) {
      const hy = y1 - half - u * 0.55 + Math.sin(t * 4) * u * 0.05;
      ctx.globalAlpha = 0.85;
      ctx.font = `900 ${u * 0.24}px ${FONT}`;
      ctx.fillStyle = tierColor(run.tier + 1);
      ctx.strokeText(`${this.labels.hold} ▲`, x, hy);
      ctx.fillText(`${this.labels.hold} ▲`, x, hy);
    }
    ctx.restore();
  }

  /** bills and coins falling across the whole sky: decoration only, nothing here can be picked up */
  private drawShower(t: number, strength: number): void {
    const { ctx, w, h, u } = this;
    const frac = (v: number) => v - Math.floor(v);
    for (let i = 0; i < 54; i++) {
      const a = frac(Math.sin(i * 12.9898) * 43758.5453);
      const b = frac(Math.sin(i * 78.233) * 12543.123);
      const c = frac(Math.sin(i * 39.425) * 9631.77);
      const span = w + u * 2;
      // falling, and drifting back as the chart runs forward
      const x = span - frac(a + ((t * (0.06 + 0.07 * b)) % 1)) * span - u;
      const y = frac(c + t * (0.16 + 0.2 * b)) * (h + u * 2) - u;
      const k = 0.55 + 0.6 * c;
      ctx.globalAlpha = strength * (0.42 + 0.35 * c);
      if (i % 3 === 0) {
        // a bill, tumbling
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(Math.sin(t * (1.5 + b * 2) + i) * 0.9);
        const bw = u * 0.46 * k;
        const bh = u * 0.24 * k * (0.35 + 0.65 * Math.abs(Math.cos(t * (2 + a * 2) + i)));
        ctx.fillStyle = '#3fbf7a';
        ctx.fillRect(-bw / 2, -bh / 2, bw, bh);
        ctx.fillStyle = '#d8ffe8';
        ctx.beginPath();
        ctx.ellipse(0, 0, bh * 0.3, bh * 0.3, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      } else {
        // a coin, spinning
        const r = u * 0.12 * k;
        ctx.fillStyle = GOLD;
        ctx.beginPath();
        ctx.ellipse(
          x,
          y,
          r * (0.25 + 0.75 * Math.abs(Math.cos(t * (3 + a * 3) + i))),
          r,
          0,
          0,
          Math.PI * 2,
        );
        ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }

  /**
   * An airdropped money bag. `ahead` = how far in front of the player it is (candles): far ahead it
   * is still high up, coming down on its parachute, and it reaches its place before the player does.
   * `alt` = its height over the ground: one that hangs in the air keeps its parachute open.
   */
  private drawBag(x: number, y: number, ahead: number, alt: number, t: number): void {
    const { ctx, u } = this;
    const far = clamp((ahead - 2.2) / 6, 0, 1);
    const airborne = far > 0 || alt > 1;
    const bx = x + (airborne ? Math.sin(t * 2.1) * u * (0.05 + 0.14 * far) : 0);
    const by = y - far * u * 5.5 + (airborne ? Math.sin(t * 3.1) * u * 0.04 : 0);
    const r = u * 0.27;
    ctx.lineJoin = 'round';
    if (airborne) {
      // the parachute: a striped canopy and its lines
      const cy = by - u * 1.05;
      const cw = u * 0.52;
      const ch = u * 0.42;
      ctx.strokeStyle = 'rgba(255,255,255,0.75)';
      ctx.lineWidth = Math.max(1, u * 0.02);
      ctx.beginPath();
      for (const k of [-1, -0.33, 0.33, 1]) {
        ctx.moveTo(bx + k * cw, cy);
        ctx.lineTo(bx + k * r * 0.35, by - r * 1.05);
      }
      ctx.stroke();
      for (let g = 0; g < 3; g++) {
        ctx.fillStyle = g === 1 ? '#f2f5f8' : RED;
        ctx.beginPath();
        ctx.moveTo(bx - cw + (g * 2 * cw) / 3, cy);
        ctx.ellipse(
          bx,
          cy,
          cw,
          ch,
          0,
          Math.PI + (g * Math.PI) / 3,
          Math.PI + ((g + 1) * Math.PI) / 3,
        );
        ctx.lineTo(bx - cw + ((g + 1) * 2 * cw) / 3, cy);
        ctx.closePath();
        ctx.fill();
      }
      ctx.strokeStyle = INK;
      ctx.lineWidth = Math.max(1.5, u * 0.04);
      ctx.beginPath();
      ctx.ellipse(bx, cy, cw, ch, 0, Math.PI, Math.PI * 2);
      ctx.closePath();
      ctx.stroke();
    }
    // a glow, then the sack with its tied neck
    ctx.globalAlpha = 0.2 + 0.08 * Math.sin(t * 5);
    ctx.fillStyle = GOLD;
    ctx.beginPath();
    ctx.arc(bx, by, r * 1.7, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.strokeStyle = INK;
    ctx.lineWidth = Math.max(1.5, u * 0.045);
    ctx.fillStyle = '#d9a441';
    ctx.beginPath();
    ctx.moveTo(bx - r * 0.3, by - r * 0.95);
    ctx.quadraticCurveTo(bx - r * 1.25, by - r * 0.2, bx - r * 0.95, by + r * 0.75);
    ctx.quadraticCurveTo(bx, by + r * 1.25, bx + r * 0.95, by + r * 0.75);
    ctx.quadraticCurveTo(bx + r * 1.25, by - r * 0.2, bx + r * 0.3, by - r * 0.95);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#b77f22';
    ctx.beginPath();
    ctx.moveTo(bx - r * 0.55, by - r * 1.4);
    ctx.lineTo(bx + r * 0.55, by - r * 1.4);
    ctx.lineTo(bx + r * 0.3, by - r * 0.92);
    ctx.lineTo(bx - r * 0.3, by - r * 0.92);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#fff3c4';
    ctx.font = `900 ${r * 1.25}px ${FONT}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('$', bx, by + r * 0.12);
  }

  private drawCoin(
    x: number,
    y: number,
    phase: number,
    moon = false,
    size = 1,
    dull = false,
  ): void {
    const { ctx, u } = this;
    if (moon) {
      // a moon coin: bigger, pale and glowing
      const r = u * 0.26;
      ctx.globalAlpha = 0.22 + 0.1 * Math.sin(phase * 5);
      ctx.fillStyle = '#bfe6ff';
      ctx.beginPath();
      ctx.arc(x, y, r * 1.9, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#f4faff';
      ctx.strokeStyle = '#5d9bd0';
      ctx.lineWidth = Math.max(1.5, u * 0.04);
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      // the dark side, so it reads as a crescent
      ctx.save();
      ctx.beginPath();
      ctx.arc(x, y, r * 0.92, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = '#8fc3ea';
      ctx.beginPath();
      ctx.arc(x + r * 0.5, y - r * 0.2, r * 0.85, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      return;
    }
    const r = u * 0.2 * size;
    const k = 0.3 + 0.7 * Math.abs(Math.cos(phase * 4));
    if (size > 1.2) {
      // a big coin glows
      ctx.globalAlpha = 0.2 + 0.08 * Math.sin(phase * 5);
      ctx.fillStyle = GOLD;
      ctx.beginPath();
      ctx.arc(x, y, r * 1.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.fillStyle = dull ? '#9c8f63' : GOLD;
    ctx.strokeStyle = dull ? '#554c31' : '#9a6b00';
    ctx.lineWidth = Math.max(1.5, u * 0.04);
    ctx.beginPath();
    ctx.ellipse(x, y, r * k, r, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = dull ? '#c9bf9a' : '#fff3c4';
    ctx.beginPath();
    ctx.ellipse(x - r * 0.25 * k, y - r * 0.25, r * 0.22 * k, r * 0.4, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  private drawItem(kind: ItemKind, x: number, y: number, t: number): void {
    const { ctx, u } = this;
    const r = u * 0.3;
    const color = kind === 'margin' ? GREEN : kind === 'shield' ? '#7ad7ff' : '#ff9f48';
    ctx.globalAlpha = 0.16 + 0.06 * Math.sin(t * 6);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, r * 1.7, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.lineWidth = Math.max(2, u * 0.05);
    ctx.strokeStyle = INK;
    if (kind === 'margin') {
      // margin top-up: a green plus
      ctx.fillStyle = GREEN;
      ctx.beginPath();
      ctx.roundRect(x - r, y - r, r * 2, r * 2, r * 0.4);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(x - r * 0.6, y - r * 0.18, r * 1.2, r * 0.36);
      ctx.fillRect(x - r * 0.18, y - r * 0.6, r * 0.36, r * 1.2);
    } else if (kind === 'shield') {
      // diamond hands
      ctx.fillStyle = '#7ad7ff';
      ctx.beginPath();
      ctx.moveTo(x - r * 1.05, y - r * 0.25);
      ctx.lineTo(x - r * 0.5, y - r * 0.9);
      ctx.lineTo(x + r * 0.5, y - r * 0.9);
      ctx.lineTo(x + r * 1.05, y - r * 0.25);
      ctx.lineTo(x, y + r);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,0.8)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x - r * 1.05, y - r * 0.25);
      ctx.lineTo(x + r * 1.05, y - r * 0.25);
      ctx.moveTo(x - r * 0.5, y - r * 0.9);
      ctx.lineTo(x, y + r);
      ctx.lineTo(x + r * 0.5, y - r * 0.9);
      ctx.stroke();
    } else {
      this.drawRocket(x, y, r * 1.15, -Math.PI / 4, t);
    }
  }

  /** a small rocket pointing along `angle` (0 = right); `flame` = the engine is burning */
  private drawRocket(
    x: number,
    y: number,
    r: number,
    angle: number,
    t: number,
    flame = true,
  ): void {
    const { ctx } = this;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    if (flame) {
      ctx.fillStyle = Math.sin(t * 40) > 0 ? '#ffd24a' : '#ff7a2f';
      ctx.beginPath();
      ctx.moveTo(-r * 0.7, -r * 0.3);
      ctx.lineTo(-r * (1.9 + 0.5 * Math.sin(t * 30)), 0);
      ctx.lineTo(-r * 0.7, r * 0.3);
      ctx.closePath();
      ctx.fill();
    }
    ctx.lineWidth = Math.max(1.5, r * 0.14);
    ctx.strokeStyle = INK;
    ctx.fillStyle = RED;
    ctx.beginPath();
    ctx.moveTo(-r * 0.75, -r * 0.75);
    ctx.lineTo(-r * 0.2, -r * 0.35);
    ctx.lineTo(-r * 0.2, r * 0.35);
    ctx.lineTo(-r * 0.75, r * 0.75);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#f2f5f8';
    ctx.beginPath();
    ctx.moveTo(-r * 0.75, -r * 0.4);
    ctx.lineTo(r * 0.35, -r * 0.4);
    ctx.quadraticCurveTo(r * 1.1, 0, r * 0.35, r * 0.4);
    ctx.lineTo(-r * 0.75, r * 0.4);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#7ad7ff';
    ctx.beginPath();
    ctx.arc(r * 0.1, 0, r * 0.18, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }

  private drawTrail(run: Run, sx: (n: number) => number, sy: (n: number) => number): void {
    const { ctx, u } = this;
    const tr = this.trail;
    if (tr.length < 2) return;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = run.bull > 0 ? GOLD : tierColor(run.tier);
    for (let i = 1; i < tr.length; i++) {
      const k = i / tr.length;
      ctx.globalAlpha = k * 0.55;
      ctx.lineWidth = u * (0.03 + 0.07 * k);
      ctx.beginPath();
      ctx.moveTo(sx(tr[i - 1].x), sy(tr[i - 1].y));
      ctx.lineTo(sx(tr[i].x), sy(tr[i].y));
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.lineCap = 'butt';
  }

  /** the fuel left in the rocket, as a small bar over the player's head */
  private drawFuel(run: Run, x: number, y: number, t: number): void {
    const { ctx, u } = this;
    const bw = u * 1.3;
    const bh = Math.max(6, u * 0.16);
    const bx = x - bw / 2;
    const by = y - u * 1.55;
    const left = run.launch > 0 ? 1 : run.fuel / ROCKET_FUEL;
    ctx.fillStyle = INK;
    ctx.beginPath();
    ctx.roundRect(bx - 2, by - 2, bw + 4, bh + 4, bh);
    ctx.fill();
    if (left > 0) {
      ctx.fillStyle = left < 0.3 ? RED : run.launch > 0 ? '#ffd24a' : '#ff9f48';
      ctx.beginPath();
      ctx.roundRect(bx, by, Math.max(bh, bw * left), bh, bh);
      ctx.fill();
    } else if (Math.floor(t * 6) % 2 === 0) {
      ctx.strokeStyle = RED;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.roundRect(bx - 2, by - 2, bw + 4, bh + 4, bh);
      ctx.stroke();
    }
  }

  /** the surfer, with the feet at screen height `feet` */
  private drawPlayer(run: Run, t: number, live: boolean, feet: number): void {
    const { ctx, u } = this;
    const flying = run.flying;
    const x = this.px;
    const y = feet - (live ? 0 : Math.sin(t * 2.4) * u * 0.05 + u * 0.05);
    const tilt = flying
      ? clamp(-run.vy * 0.045, -0.45, 0.45)
      : run.grounded
        ? 0
        : clamp(-run.vy * 0.03, -0.5, 0.45);
    if (flying) this.drawFuel(run, x, y, t);
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(tilt);
    const bull = run.bull > 0;
    if (run.invuln > 0 && !flying && !bull && Math.floor(t * 14) % 2 === 0) ctx.globalAlpha = 0.45;

    if (flying) this.drawRocket(-u * 0.25, -u * 0.02, u * 0.5, 0, t, run.thrusting);

    // the board
    const color = tierColor(run.tier);
    ctx.lineWidth = Math.max(2, u * 0.05);
    ctx.strokeStyle = INK;
    ctx.fillStyle = '#f2f5f8';
    ctx.beginPath();
    ctx.moveTo(-u * 0.62, -u * 0.05);
    ctx.quadraticCurveTo(-u * 0.7, -u * 0.16, -u * 0.5, -u * 0.17);
    ctx.lineTo(u * 0.45, -u * 0.17);
    ctx.quadraticCurveTo(u * 0.78, -u * 0.17, u * 0.82, -u * 0.26);
    ctx.quadraticCurveTo(u * 0.8, -u * 0.02, u * 0.45, -u * 0.02);
    ctx.lineTo(-u * 0.5, -u * 0.02);
    ctx.quadraticCurveTo(-u * 0.6, -u * 0.02, -u * 0.62, -u * 0.05);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.fillRect(-u * 0.38, -u * 0.125, u * 0.7, u * 0.06);

    // the SNEK, flipped to face the way it is going
    const img = this.heads[Math.min(this.heads.length - 1, run.tier)];
    const size = u * 1.1;
    if (img?.complete && img.naturalWidth > 0) {
      ctx.save();
      ctx.translate(-u * 0.05, -u * 0.15);
      ctx.scale(-1, 1);
      ctx.drawImage(img, -NECK.x * size, -NECK.y * size, size, size);
      ctx.restore();
    } else {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(0, -u * 0.55, u * 0.38, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
    if (run.shield) {
      ctx.globalAlpha = 0.16 + 0.05 * Math.sin(t * 6);
      ctx.fillStyle = '#7ad7ff';
      ctx.beginPath();
      ctx.arc(0, -u * 0.5, u * 0.78, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 0.8;
      ctx.strokeStyle = '#7ad7ff';
      ctx.lineWidth = Math.max(2, u * 0.05);
      ctx.stroke();
    }
    ctx.restore();
  }

  private drawParticles(dt: number, sx: (n: number) => number, sy: (n: number) => number): void {
    const { ctx, u } = this;
    for (let i = this.parts.length - 1; i >= 0; i--) {
      const p = this.parts[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.parts.splice(i, 1);
        continue;
      }
      p.vy -= p.gravity * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      ctx.globalAlpha = Math.min(1, p.life / p.max + 0.1);
      ctx.fillStyle = p.color;
      const s = p.size * u;
      ctx.fillRect(sx(p.x) - s / 2, sy(p.y) - s / 2, s, s);
    }
    ctx.globalAlpha = 1;
  }

  private drawTexts(dt: number, sx: (n: number) => number, sy: (n: number) => number): void {
    const { ctx, u, w } = this;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const f = this.texts[i];
      f.life -= dt;
      if (f.life <= 0) {
        this.texts.splice(i, 1);
        continue;
      }
      f.y += dt * 0.9;
      const px = Math.max(14, Math.min(u * 0.4, 30)) * f.size;
      ctx.font = `900 ${px}px ${FONT}`;
      ctx.globalAlpha = Math.min(1, f.life / 0.4);
      const half = ctx.measureText(f.str).width / 2 + 8;
      const x = clamp(sx(f.x), half, w - half);
      ctx.lineWidth = Math.max(3, px * 0.22);
      ctx.strokeStyle = INK;
      ctx.strokeText(f.str, x, sy(f.y));
      ctx.fillStyle = f.color;
      ctx.fillText(f.str, x, sy(f.y));
    }
    ctx.globalAlpha = 1;
  }
}
